-- composition of rule kernels CoverIdxScan x OrderBySubq (sqlite), template graft_scalar
WITH cte1 AS MATERIALIZED (SELECT CAST(5e-324 AS REAL) AS c0 ORDER BY 1) SELECT CAST(1 AS INTEGER) AS c0, CAST(1.5 AS NUMERIC) AS c1 FROM (SELECT * FROM cte1 WHERE (SELECT count(*) FROM (SELECT '{"k": 1, "a": [1, 2]}' AS c0 FROM tp AS a1 WHERE ((a1.c1, TRUE) <> (CASE WHEN FALSE THEN a1.c1 ELSE CONCAT_WS ('-', FALSE, (SELECT SUM (CAST(5e-324 AS REAL)) FROM t3 AS a2)) END, TRUE)) GROUP BY a1.c0, a1.c1) AS kb) >= 0) AS a1 GROUP BY a1.c0 UNION SELECT CAST(1 AS INTEGER) AS c0, CAST(42.5 AS NUMERIC) AS c1;
